/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountTeamInvite, type TeamInviteOptions } from "../../components/team-invite/TeamInviteEngine.js";
import type { MotionController } from "../../components/team-invite/motion-runtime";

export function TeamInvite(props: { options?: TeamInviteOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountTeamInvite(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="team-invite" />;
}

